{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify metadata_options, defaulting to IMDSv1 which allows SSRF attacks to steal credentials. Enforcing IMDSv2 by setting http_tokens to 'required' mitigates this risk."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The root block device mapping does not have encryption enabled (encrypted = true). Data at rest on the EBS volume will be unencrypted, violating security best practices for data protection."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Added metadata_options block with http_tokens set to 'required' to enforce IMDSv2 and prevent SSRF credential theft. Added root_block_device block with encrypted set to true to ensure data at rest on the EBS volume is encrypted."
}
